[assembly: KSPAssembly("PersistentFlight.CircularTransferTests",0,25)]
[KSPAddon(KSPAddon.Startup.MainMenu,true)]
public sealed class CircularTransferHarness:MonoBehaviour {
 string result;int phase,index;float deadline;double stamp,fuel,firstUT,sourceDV,nextLog;MissionTemplate template;Guid destination;GoalOrbitPreview preview;ManeuverNode[] applied;bool firstReported,warpReported;
 readonly TemplateGoal[] kinds={TemplateGoal.CircularizeApoapsis,TemplateGoal.CircularizePeriapsis,TemplateGoal.OppositeFromApoapsis,TemplateGoal.OppositeFromPeriapsis,TemplateGoal.CircularAltitude,TemplateGoal.CircularAltitude,TemplateGoal.CircularAltitude,TemplateGoal.CircularAltitude,TemplateGoal.CircularAltitude};
 void Awake(){DontDestroyOnLoad(this);}void Note(string s){File.AppendAllText(result,s+Environment.NewLine);Debug.Log("[PF-CIRCULAR-TEST] "+s);}void Check(bool b,string s){if(!b)throw new Exception(s);}void Reject(Action a,string s){bool denied=false;try{a();}catch(InvalidOperationException){denied=true;}catch(ArgumentException){denied=true;}Check(denied,s);}double Fuel(Vessel v){double c;return MissionControl.Resource(v,"LiquidFuel",out c);}
 IEnumerator Start(){result=Path.Combine(KSPUtil.ApplicationRootPath,"pf-circular-result.txt");File.WriteAllText(result,"");deadline=Time.realtimeSinceStartup+1800;yield return new WaitForSeconds(3);try{Prepare();}catch(Exception e){Note("FAIL prepare "+e);Application.Quit();}}
 void Update(){if(result==null||!HighLogic.LoadedSceneIsFlight||!FlightGlobals.ready)return;try{
  Check(Time.realtimeSinceStartup<deadline,"Timeout phase "+phase);double now=Planetarium.GetUniversalTime();var source=FlightGlobals.Vessels.FirstOrDefault(v=>v.vesselName=="MC FOCUS");var craft=FlightGlobals.Vessels.FirstOrDefault(v=>v.vesselName=="MC PILOT");if(now>=nextLog){Debug.Log("[PF-CIRCULAR-TEST] phase="+phase+" UT="+now+" queued="+(craft==null?-1:MissionControl.Modules(craft).Sum(m=>m.QueueCount)));nextLog=now+30;}
  if(phase==0&&source!=null&&craft!=null&&source.loaded&&!source.packed&&craft.loaded&&!craft.packed&&now>10008){
   template=MissionTemplateFlight.CreateGoal(source,"Reach a circular orbit at 160 km",TemplateGoal.CircularAltitude,160000);sourceDV=MissionTemplateFlight.PreviewGoal(source,template).DV;MissionTemplateStore.Save(MissionTemplateFlight.Folder,template);template=MissionTemplateStore.Load(MissionTemplateFlight.Folder,template.Id);Check(template.Goal==TemplateGoal.CircularAltitude&&template.TargetAltitude==160000&&template.Steps.Count==0,"Circular goal persisted copied burns");
   MapView.EnterMapView();var n=source.patchedConicSolver.AddManeuverNode(now+120);n.OnGizmoUpdated(new Vector3d(0,0,10),n.UT);source.patchedConicSolver.UpdateFlightPlan();double f=Fuel(source);Reject(()=>MissionTemplateFlight.Apply(source,template,0),"Existing map plan overwritten");Check(source.patchedConicSolver.maneuverNodes.Count==1&&Fuel(source)==f&&source.ctrlState.mainThrottle==0,"Refusal changed existing plan or controls");n.RemoveSelf();source.patchedConicSolver.UpdateFlightPlan();Check(RegionFlightRunner.Instance.Focus(craft),"Destination focus failed");destination=craft.id;stamp=now;phase=1;Note("PASS circular goal checked-file persistence without source burns; existing map plan preserved");
  }
  else if(phase==1&&craft==FlightGlobals.ActiveVessel&&MissionControl.Pilot(craft)!=null&&now-stamp>2){
   fuel=Fuel(craft);var wrong=MissionTemplateStore.Decode(MissionTemplateStore.Encode(template));wrong.Body="Mun";Reject(()=>MissionTemplateFlight.PreviewGoal(craft,wrong),"Wrong body preview accepted");Reject(()=>MissionTemplateFlight.Apply(craft,wrong,0),"Wrong body apply accepted");var unsafeGoal=MissionTemplateStore.Decode(MissionTemplateStore.Encode(template));unsafeGoal.TargetAltitude=60000;Reject(()=>MissionTemplateFlight.Apply(craft,unsafeGoal,0),"Atmospheric circle accepted");craft.ctrlState.mainThrottle=.1f;try{Reject(()=>MissionTemplateFlight.Apply(craft,template,0),"Powered craft accepted");}finally{craft.ctrlState.mainThrottle=0;}
   Check(craft.patchedConicSolver.maneuverNodes.Count==0&&MissionControl.Modules(craft).All(m=>m.QueueCount==0)&&Fuel(craft)==fuel,"Rejected circular goals mutated destination");Check(Math.Abs(MissionTemplateFlight.PreviewGoal(craft,template).DV-sourceDV)>1,"Destination copied source burns");phase=2;Note("PASS destination-specific recalculation and wrong-body/atmosphere/powered-craft refusal without map/control writes");
  }
  else if(phase==2){var goal=MissionTemplateStore.Decode(MissionTemplateStore.Encode(template));goal.Goal=kinds[index];goal.TargetAltitude=index==2?115000:index==3?180000:index==4?160000:index==5?90000:index==6?120000:index==7?craft.orbit.ApA:index==8?craft.orbit.PeA:0;preview=MissionTemplateFlight.PreviewGoal(craft,goal);Check(craft.patchedConicSolver.maneuverNodes.Count==0&&Fuel(craft)==fuel&&craft.ctrlState.mainThrottle==0&&MissionControl.Modules(craft).All(m=>m.QueueCount==0),"Preview mutated map/fuel/controls");applied=MissionTemplateFlight.Apply(craft,goal,0);Check(applied.Length==preview.Burns.Length,"Calculated node count wrong");if(index>=4&&index<=6)Check(applied.Length==2,"Transfer did not create two nodes");if(index>=7)Check(applied.Length==1,"Existing target apsis did not collapse to one node");for(int i=0;i<applied.Length;i++)Check(Math.Abs(applied[i].UT-preview.Burns[i].UT)<.01&&Math.Abs(applied[i].DeltaV.z-preview.Burns[i].Prograde)<.001,"Fresh node differs from calculated burn");stamp=now;phase=3;}
  else if(phase==3&&now-stamp>2&&applied.All(n=>n.nextPatch!=null)){for(int i=0;i<applied.Length;i++){var n=applied[i];var b=preview.Burns[i];Check(n.patch.referenceBody==craft.mainBody&&n.nextPatch.referenceBody==craft.mainBody,"Transfer changed body");Check(Math.Abs(n.nextPatch.PeA-b.PeriapsisAltitude)<5&&Math.Abs(n.nextPatch.ApA-b.ApoapsisAltitude)<5,"Native patch disagrees for case "+index+" burn "+i+": "+n.nextPatch.PeA+" / "+n.nextPatch.ApA);}Check(Fuel(craft)==fuel&&craft.ctrlState.mainThrottle==0&&MissionControl.Modules(craft).All(m=>m.QueueCount==0),"Map application started mission");Note("PASS native map case "+index+" ("+GoalOrbitMath.Label(kinds[index])+") matches every burn within 5 m; preview/application did not queue or thrust");foreach(var n in applied)n.RemoveSelf();craft.patchedConicSolver.UpdateFlightPlan();index++;phase=index<kinds.Length?2:4;}
  else if(phase==4){var panel=FindObjectOfType<RegionalFleetPanel>();var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(RegionalFleetPanel).GetField("showTemplates",flags).SetValue(panel,true);typeof(RegionalFleetPanel).GetField("selectedTemplate",flags).SetValue(panel,template.Id);typeof(RegionalFleetPanel).GetField("goalChoice",flags).SetValue(panel,4);typeof(RegionalFleetPanel).GetField("goalAltitude",flags).SetValue(panel,"160");typeof(RegionalFleetPanel).GetField("templateScroll",flags).SetValue(panel,new Vector2(0,170));typeof(RegionalFleetPanel).GetMethod("SetOpen",flags).Invoke(panel,new object[]{true});stamp=now;phase=5;}
  else if(phase==5&&now-stamp>2){ScreenCapture.CaptureScreenshot(Path.Combine(KSPUtil.ApplicationRootPath,"circular-template-preview.png"));stamp=now;phase=6;}
  else if(phase==6&&now-stamp>2){var panel=FindObjectOfType<RegionalFleetPanel>();typeof(RegionalFleetPanel).GetMethod("SetOpen",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(panel,new object[]{false});preview=MissionTemplateFlight.PreviewGoal(craft,template);Check(FleetFuelForecast.Evaluate(MissionControl.Pilot(craft),preview.DV).State.ToString()!="Unknown","Combined fuel forecast unavailable");applied=MissionTemplateFlight.Apply(craft,template,0);Check(applied.Length==2,"Execution goal missing transfer burn");firstUT=applied[0].UT;stamp=now;phase=7;}
  else if(phase==7&&now-stamp>2&&applied.All(n=>n.nextPatch!=null)){MissionQueue.QueuePlan(craft,MissionControl.Pilot(craft));Check(MissionControl.Pilot(craft).QueueCount==2,"Transfer did not queue both burns");Reject(()=>MissionTemplateFlight.Apply(craft,template,0),"Busy craft accepted");GamePersistence.SaveGame("circular-queued",HighLogic.SaveFolder,SaveMode.OVERWRITE);var game=GamePersistence.LoadGame("circular-queued",HighLogic.SaveFolder,true,false);int i=game.flightState.protoVessels.FindIndex(v=>v.vesselID==destination);FlightDriver.StartAndFocusVessel(game,i);stamp=now;phase=8;Note("PASS two-burn UI and total fuel advisory; explicit queue and cold scene reload requested");}
  else if(phase==8&&craft!=null&&craft.id==destination&&craft.loaded&&!craft.packed&&now-stamp>5&&MissionControl.Pilot(craft)!=null){var m=MissionControl.Pilot(craft);Check(m.QueueCount==2&&Math.Abs(m.nodeUT-firstUT)<.001,"Two-burn queue lost on reload");Check(MissionTemplateStore.Load(MissionTemplateFlight.Folder,template.Id).Goal==TemplateGoal.CircularAltitude,"Target altitude goal lost on reload");MapView.ExitMapView();Check(RegionFlightRunner.Instance.Focus(source),"Unfocus destination failed");foreach(var other in MissionControl.Modules(source))other.guardWarp=false;phase=9;Note("PASS cold-load circular goal and both calculated maneuvers retained; craft unfocused");}
  else if(phase==9){var m=MissionControl.Modules(craft).First();Check(!m.missionHold,"Circular goal execution held: "+m.nodeStatus);if(m.QueueCount==1&&!firstReported){firstReported=true;Note("PASS first real unfocused transfer burn completed; circularization automatically promoted");}if(m.warpReady&&m.warpUntil-now>120&&TimeWarp.CurrentRate==1){TimeWarp.SetRate(2,true);FleetDirector.Instance.ProtectWarp();if(TimeWarp.CurrentRate>1&&!warpReported){warpReported=true;Note("PASS real pilot coast lease permitted native time warp between burns");}}
   if(m.QueueCount==0){if(TimeWarp.CurrentRate!=1)TimeWarp.SetRate(0,true);var reports=PersistentFlightScenario.Instance.Debriefs.Records.Where(r=>r.Vessel==destination&&r.Mode==DebriefMode.LiveManeuver).ToArray();Check(firstReported&&reports.Length==2&&reports.All(r=>r.Finished&&r.Outcome=="Complete"&&r.ResidualDV<=.5)&&Fuel(craft)<fuel,"Both actual unfocused burns did not complete");Check(Math.Abs(craft.orbit.ApA-160000)<2000&&Math.Abs(craft.orbit.PeA-160000)<2000,"Actual orbit missed target altitude: "+craft.orbit.PeA+" / "+craft.orbit.ApA);File.Copy(RegionalFleetPanel.ExportFlightDebriefs(),Path.Combine(KSPUtil.ApplicationRootPath,"circular-flight-debrief.csv"),true);Note("PASS both actual unfocused burns completed after reload; residual <=0.5 m/s each and both target apsides within 2000 m");Note("PASS ALL CIRCULAR TRANSFER NATIVE OPERATIONS");stamp=now;phase=10;}}
  else if(phase==10&&now-stamp>2){Application.Quit();phase=11;}
 }catch(Exception e){Note("FAIL "+e);phase=99;Application.Quit();}}
    void Prepare(){
        string folder="PFCircular-"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(Path.Combine(KSPUtil.ApplicationRootPath,"saves",folder));
        var root=ConfigNode.Load(Path.Combine(KSPUtil.ApplicationRootPath,"saves/PersistentFlightTest/template.sfs"));var g=root.GetNode("GAME");g.SetValue("Title","Mission control disposable test (SANDBOX)");g.SetValue("Mode","SANDBOX");g.SetValue("scene","5");
        var fs=g.GetNode("FLIGHTSTATE");var source=fs.GetNodes("VESSEL").First(v=>v.GetNodes("PART").Any(p=>p.GetNodes("MODULE").Any(m=>m.GetValue("name")=="kOSProcessor")));
        var originals=source.GetNodes("PART");var cpu=originals.SelectMany(p=>p.GetNodes("MODULE")).First(m=>m.GetValue("name")=="kOSProcessor").CreateCopy();
        var tiny=new[]{originals.First(p=>p.GetValue("name")=="landerCabinSmall").CreateCopy(),originals.First(p=>p.GetValue("name")=="fuelTank.long").CreateCopy(),originals.First(p=>p.GetValue("name")=="liquidEngine3.v2").CreateCopy()};
        fs.RemoveNodes("VESSEL");fs.SetValue("UT","10000");fs.SetValue("activeVessel","0",true);
        for(int i=0;i<3;i++){
            var v=source.CreateCopy();v.RemoveNodes("PART");v.SetValue("ref",(920000+i*100).ToString());v.SetValue("pid",Guid.NewGuid().ToString("N"));v.SetValue("persistentId",(920000+i*100).ToString());
            v.SetValue("name",i==0?"MC FOCUS":i==1?"MC PILOT":"MC REMOTE");v.SetValue("sit","ORBITING");v.SetValue("landed","False");v.SetValue("splashed","False");v.SetValue("type","Probe");v.SetValue("alt","100000");v.SetValue("hgt","100000");v.SetValue("lat","0");v.SetValue("lon","0");v.SetValue("rot","0,0,0,1");v.SetValue("landedAt","");v.RemoveNodes("FLIGHTPLAN");
            var orbit=v.GetNode("ORBIT");orbit.SetValue("SMA",i==2?"300000":i==1?"720000":"732800");orbit.SetValue("ECC",i==0?((760000d-705600)/(760000+705600)).ToString("R",System.Globalization.CultureInfo.InvariantCulture):i==1?"0.02":"0");orbit.SetValue("INC","0");orbit.SetValue("LPE","0");orbit.SetValue("LAN","0");orbit.SetValue("MNA",(-Math.Sqrt(3.5316e12/Math.Pow(i==1?720000:732800,3))*150).ToString("R",System.Globalization.CultureInfo.InvariantCulture));orbit.SetValue("EPH","10000");orbit.SetValue("REF",i==2?"2":"1");
            v.GetNode("CTRLSTATE").SetValue("mainThrottle","0");
            for(int n=0;n<3;n++){
                var p=tiny[n].CreateCopy();p.SetValue("uid",(920000+i*100+n).ToString());p.SetValue("persistentId",(920000+i*100+n).ToString(),true);p.SetValue("parent",n==0?"0":(n-1).ToString());p.SetValue("position","0,"+(-3*n)+",0");p.SetValue("rotation","0,0,0,1");p.RemoveValues("attN");p.RemoveValues("sym");p.RemoveValues("crew");p.SetValue("srfN",", -1");p.SetValue("attm","0");p.SetValue("autostrutMode","Off");
                if(n>0)p.AddValue("attN","top, "+(n-1));if(n<2)p.AddValue("attN","bottom, "+(n+1));
                foreach(var m in p.GetNodes("MODULE").Where(m=>new[]{"kOSProcessor","ModulePersistentFlight","ModuleRegionalAutonomy","MechJebCore","ModuleTripLogger","KOSNameTag"}.Contains(m.GetValue("name"))))p.RemoveNode(m);
                foreach(var r in p.GetNodes("RESOURCE"))r.SetValue("amount",r.GetValue("maxAmount"));
                foreach(var m in p.GetNodes("MODULE").Where(m=>m.GetValue("name")=="ModuleEngines"||m.GetValue("name")=="ModuleEnginesFX")){m.SetValue("EngineIgnited","False",true);m.SetValue("engineShutdown","False",true);}
                if(n==0){var c=cpu.CreateCopy();c.RemoveNodes("harddisk");c.SetValue("activated",i!=2?"True":"False",true);c.SetValue("bootFile",i==1?"boot/pf_mission_test.ks":i==0?"boot/pf_event_test.ks":"None",true);p.AddNode(c);
                    var keep=p.AddNode("MODULE");keep.AddValue("name","ModulePersistentFlight");keep.AddValue("armed",i==2?"False":"True");keep.AddValue("rangeKm","60");
                    var auto=p.AddNode("MODULE");auto.AddValue("name","ModuleRegionalAutonomy");auto.AddValue("automatic",i==2?"False":"True");auto.AddValue("recordFlight","True");
                }
                if(n==2){var tag=p.AddNode("MODULE");tag.AddValue("name","KOSNameTag");tag.AddValue("nameTag","NODE_ENGINE");}v.AddNode(p);
            }
            fs.AddNode(v);
        }
        root.Save(Path.Combine(KSPUtil.ApplicationRootPath,"saves/"+folder+"/mc.sfs"));HighLogic.SaveFolder=folder;
        var game=GamePersistence.LoadGame("mc",HighLogic.SaveFolder,true,false);game.startScene=GameScenes.FLIGHT;game.flightState.activeVesselIdx=0;HighLogic.CurrentGame=game;game.Start();
    }

